mapper.select:
SELECT AB.ID, AB.CREATOR, AB.CREATE_TIME, AB.MODIFIER, AB.MODIFY_TIME, AB.LOGIC_DEL, AB.REC_VER, AB.BUILD_IN, AB.TENANT_ID, AB.BUDGET_DESC, AB.OUTLAY, AB.DURATION_FROM, AB.DURATION_TO, AB.BUDGET_TYPE, AB.USER_ID, AB.STRATEGY_ID, AB.REMARK, TENANT.NAME AS TENANT_NAME FROM account_budget AB LEFT JOIN sys_tenant TENANT ON AB.TENANT_ID = TENANT.ID WHERE AB.LOGIC_DEL = 0
AND AB.TENANT_ID = #{accountBudgetDto.tenantId}
AND AB.USER_ID = #{accountBudgetDto.userId}

SELECT IF(ACUA.AMOUNT IS NOT NULL AND ACUA.AMOUNT >= 0, ACUA.AMOUNT, AC.OUTLAY) AS OUTLAY,
       #{findBudgetCapacityDto.durationFrom} AS DURATION_FROM,
       #{findBudgetCapacityDto.durationTo}   AS DURATION_TO
FROM account_cost AC
         LEFT JOIN account_cost_user_alloc ACUA ON ACUA.COST_ID = AC.ID

WHERE AC.LOGIC_DEL = 0
  AND AC.PAYMENT_SIGN = 'EXPENSES'

      AND AC.TENANT_ID = #{findBudgetCapacityDto.tenantId}

  AND AC.USER_ID = #{findBudgetCapacityDto.userId}

      AND AC.PAYMENT_TIME >= #{findBudgetCapacityDto.durationFrom}
      AND AC.PAYMENT_TIME <= #{findBudgetCapacityDto.durationTo}

GROUP BY AC.ID

UNION ALL

SELECT IF(ACUA.AMOUNT IS NOT NULL AND ACUA.AMOUNT >= 0, ACUA.AMOUNT, AC.OUTLAY) AS OUTLAY,
       #{findBudgetCapacityDto.durationFrom} AS DURATION_FROM,
       #{findBudgetCapacityDto.durationTo}   AS DURATION_TO
FROM account_cost AC
         LEFT JOIN account_cost_user_alloc ACUA ON ACUA.COST_ID = AC.ID AND ACUA.USER_ID = #{findBudgetCapacityDto.userId}

WHERE AC.LOGIC_DEL = 0
  AND AC.PAYMENT_SIGN = 'EXPENSES'

      AND AC.TENANT_ID = #{findBudgetCapacityDto.tenantId}

  AND AC.USER_ID <> #{findBudgetCapacityDto.userId}
  AND ACUA.USER_ID = #{findBudgetCapacityDto.userId}

      AND AC.PAYMENT_TIME >= #{findBudgetCapacityDto.durationFrom}
      AND AC.PAYMENT_TIME <= #{findBudgetCapacityDto.durationTo}

GROUP BY AC.ID

